// Generated by vibelang from src/server/GitLabPullRequestCli.vibe; the migrate flow writes it again with each batch.
export function actionArgs(action, mergeMethod) {
    switch (action) {
        case "merge":
            return [
                "merge",
                // glab defaults to auto-merge during a running pipeline.
                "--auto-merge=false",
                "--yes",
                ...(mergeMethod === "squash" ? ["--squash"] : []),
            ];
        case "enable-auto-merge":
            return [
                "merge",
                "--auto-merge=true",
                "--yes",
                ...(mergeMethod === "squash" ? ["--squash"] : []),
            ];
        case "disable-auto-merge":
            return [];
        case "ready":
            return ["update", "--ready"];
        case "draft":
            return ["update", "--draft"];
        case "close":
            return ["close"];
        case "update-branch":
            return ["rebase"];
        case "reopen":
            return ["reopen"];
        case "revert":
        case "approve-workflows":
        case "delete-branch":
            throw new Error(`GitLab merge request action ${action} is unsupported`);
    }
}
